h1 {
  color: #2563eb;
  font-family: system-ui, sans-serif;
}

.lead {
  font-size: 20px;
  font-weight: 600;
  color: #0f172a;
}

p {
  color: #475569;
  line-height: 1.6;
}

.box {
  background: #dbeafe;
  border: 3px solid #2563eb;
  padding: 16px;      /* воздух внутри */
  margin: 12px;       /* отступ снаружи */
  width: 200px;
}

.row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  background: #f1f5f9;
  padding: 12px;
}

.item {
  background: #2563eb;
  color: #fff;
  padding: 18px 26px;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}

