.grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 10px;
}

.cell {
  background: #e0f2fe;
  border: 1px solid #38bdf8;
  padding: 18px;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}

.wide {
  grid-column: span 2;   /* ячейка на две колонки */
  background: #bae6fd;
}

/* база — для узкого экрана */
.cards {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}

/* добавляем на широком */
@media (min-width: 700px) {
  .cards { grid-template-columns: repeat(3, 1fr); }
}

.card {
  background: #dcfce7;
  border: 1px solid #22c55e;
  padding: 16px;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}
.hint { font: 14px system-ui; color: #64748b; }

:root {
  --brand: #2563eb;
  --radius: 10px;
}

.btn {
  background: var(--brand);
  color: #fff;
  border: 0;
  padding: 12px 20px;
  border-radius: var(--radius);
  font: 15px system-ui;
  cursor: pointer;
  transition: background .2s, transform .2s;
}

.btn:hover {
  background: #1d4ed8;
  transform: translateY(-2px);
}

.panel {
  margin-top: 16px;
  padding: 18px;
  border-radius: var(--radius);
  background: #fff;
  box-shadow: 0 4px 14px rgba(15, 23, 42, .12);
  font: 15px system-ui;
}

tasks.tests:
const g = $('.gallery');
assert(g, 'Не найден .gallery');
equal(style(g, 'display'), 'grid', 'display');
const cols = style(g, 'grid-template-columns').split(' ').filter(Boolean);
equal(cols.length, 3, 'Количество колонок');
assert(style(g, 'gap').indexOf('12px') === 0, 'gap должен быть 12px, а сейчас: ' + style(g, 'gap'));

const t = $('.tag');
assert(t, 'Не найден .tag');
equal(style(t, 'background-color'), 'rgb(22, 163, 74)', 'Фон должен прийти из переменной');
equal(style(t, 'color'), 'rgb(255, 255, 255)', 'Цвет текста');
const rootVar = getComputedStyle(document.documentElement).getPropertyValue('--main').trim();
assert(rootVar.length > 0, 'Переменная --main должна быть объявлена в :root');

const c = $('.cta');
assert(c, 'Не найден .cta');
equal(style(c, 'background-color'), 'rgb(124, 58, 237)', 'Фон');
equal(style(c, 'border-top-left-radius'), '8px', 'Скругление');
equal(style(c, 'transition-duration'), '0.3s', 'Длительность перехода');
equal(style(c, 'transition-property'), 'all', 'Переход применён ко всем свойствам');

const l = $('.list');
assert(l, 'Не найден .list');
equal(style(l, 'display'), 'grid', 'display');
assert(style(l, 'gap').indexOf('16px') === 0, 'gap должен быть 16px, а сейчас: ' + style(l, 'gap'));
const cols = style(l, 'grid-template-columns').split(' ').filter(Boolean);
equal(cols.length, 2, 'На широком экране должно быть две колонки');

blocks.code:
.demo { display: flex; gap: 16px; margin-bottom: 20px; }

.card {
  position: relative;        /* якорь для absolute внутри */
  width: 180px;
  padding: 20px;
  background: #f1f5f9;
  border-radius: 12px;
}

.badge {
  position: absolute;        /* считается от .card, а не от страницы */
  top: -8px;
  right: -8px;
  background: #2563eb;
  color: white;
  font-size: 12px;
  padding: 4px 8px;
  border-radius: 999px;
}

.scroll {
  height: 140px;
  overflow-y: auto;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
}

.sticky-head {
  position: sticky;          /* обычный, пока не упрётся в верх */
  top: 0;
  background: #0f172a;
  color: white;
  padding: 8px 12px;
}

.scroll p { margin: 12px; }

/* специфичность 1: слабее всех */
p { color: #64748b; }

/* 10: класс сильнее тега */
.text { color: #2563eb; }

/* 20: два класса сильнее одного */
.text.special { color: #db2777; }

/* 100: идентификатор сильнее любых классов */
#one { color: #ea580c; }

.box {
  padding: 16px;
  background: #f8fafc;
  border-radius: 10px;
  font-family: system-ui, sans-serif;
}

.box p { margin: 8px 0; font-weight: 600; }

/* Какой цвет будет у <p class="a b">? */
.a { color: red; }
.b { color: blue; }

.row {
  display: flex;
  gap: 20px;
  align-items: center;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.btn {
  padding: 10px 18px;
  border: none;
  border-radius: 8px;
  background: #2563eb;
  color: white;
  font-size: 15px;
  cursor: pointer;
  /* что анимировать, сколько и с каким ускорением */
  transition: transform 0.2s ease, background 0.2s ease;
}

.btn:hover {
  background: #1d4ed8;
  transform: translateY(-2px) scale(1.03);
}

.btn:active { transform: translateY(0) scale(0.98); }

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.35; }
}

.pulse {
  padding: 10px 14px;
  background: #fde68a;
  border-radius: 8px;
  animation: pulse 1.6s ease-in-out infinite;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

.spin {
  padding: 10px 14px;
  background: #bbf7d0;
  border-radius: 8px;
  animation: spin 3s linear infinite;
}

/* уважение к настройке «меньше движения» в системе */
@media (prefers-reduced-motion: reduce) {
  .btn, .pulse, .spin { animation: none; transition: none; }
}

